-- OPCIONAL: limpia exclusivamente la ficha creada por 10, tras enviarla a papelera desde la aplicacion.
-- Para fichas de prueba con matriculas/cuotas usar Papelera > Revisar > Eliminar (validacion firmada).
-- No borra auditorias, constancias ni catalogos; si hay nuevas dependencias la FK revierte todo.
SET NOCOUNT ON; SET XACT_ABORT ON;
DECLARE @Ejecutar bit=0,@Confirmacion nvarchar(80)=N'REVISAR',@Administrador varchar(20)=NULL;
SELECT a.DNI_ALUMNO,a.NOMBRE_COMPLETO,a.ES_PRUEBA,u.ID_USUARIO,u.ACTIVO,p.ESTADO
 FROM dbo.ALUMNO a LEFT JOIN dbo.USUARIO u ON u.DNI_ALUMNO=a.DNI_ALUMNO
 LEFT JOIN dbo.PAPELERA_REGISTRO p ON p.ENTIDAD='ALUMNO' AND p.ID_REGISTRO=a.DNI_ALUMNO AND p.ESTADO='EN_PAPELERA' WHERE a.DNI_ALUMNO='45999999';
IF @Ejecutar=0 RETURN;
IF DB_NAME() NOT LIKE 'FractalesAcademy[_]Pruebas[_]V4[_]5[_]%' THROW 54511,'Solo base local de ensayo.',1;
IF @Confirmacion<>N'ELIMINAR FICTICIO 45999999' THROW 54511,'Revisa las dependencias y confirma el identificador exacto.',1;
BEGIN TRY BEGIN TRAN;
IF NOT EXISTS(SELECT 1 FROM dbo.USUARIO WITH(UPDLOCK,HOLDLOCK) WHERE ID_USUARIO=@Administrador AND ID_ROL='ADMIN' AND ACTIVO=1) THROW 54511,'Selecciona administrador activo.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.ALUMNO WITH(UPDLOCK,HOLDLOCK) WHERE DNI_ALUMNO='45999999' AND ES_PRUEBA=1 AND NOMBRE_COMPLETO='Estudiante ficticio SQL V45') THROW 54511,'La ficha no corresponde a la prueba explicita de 10.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.PAPELERA_REGISTRO WITH(UPDLOCK,HOLDLOCK) WHERE ENTIDAD='ALUMNO' AND ID_REGISTRO='45999999' AND ESTADO='EN_PAPELERA') THROW 54511,'Envia primero la ficha a papelera.',1;
IF EXISTS(SELECT 1 FROM dbo.USUARIO WITH(UPDLOCK,HOLDLOCK) WHERE DNI_ALUMNO='45999999' AND (ACTIVO=1 OR ID_USUARIO<>'V45-TEST-SQL'))
 OR EXISTS(SELECT 1 FROM dbo.ESTADO_ALUMNO WITH(UPDLOCK,HOLDLOCK) WHERE DNI_ALUMNO='45999999' AND ACTIVO=1)
 THROW 54511,'Cuenta/ficha activa o diferente. Revision manual requerida.',1;
IF EXISTS(SELECT 1 FROM dbo.MATRICULA WITH(UPDLOCK,HOLDLOCK) WHERE DNI_ALUMNO='45999999')
 OR EXISTS(SELECT 1 FROM dbo.PAGO WITH(UPDLOCK,HOLDLOCK) WHERE DNI_ALUMNO='45999999')
 OR EXISTS(SELECT 1 FROM dbo.CONTACTO_VERIFICADO WITH(UPDLOCK,HOLDLOCK) WHERE DNI_ALUMNO='45999999')
 OR EXISTS(SELECT 1 FROM dbo.SOLICITUD_CONTACTO WITH(UPDLOCK,HOLDLOCK) WHERE DNI_ALUMNO='45999999')
 OR EXISTS(SELECT 1 FROM dbo.CODIGO_CUENTA WITH(UPDLOCK,HOLDLOCK) WHERE ID_USUARIO_RESPONSABLE='V45-TEST-SQL')
 THROW 54511,'Hay relaciones adicionales. Usa la revision completa en Papelera; no se eliminan mediante este script.',1;
DELETE dbo.SEGURIDAD_USUARIO WHERE ID_USUARIO_RESPONSABLE='V45-TEST-SQL';
DELETE dbo.ESTADO_ALUMNO WHERE DNI_ALUMNO='45999999';
DELETE dbo.USUARIO WHERE ID_USUARIO='V45-TEST-SQL' AND DNI_ALUMNO='45999999' AND ACTIVO=0;
DELETE dbo.ALUMNO WHERE DNI_ALUMNO='45999999' AND ES_PRUEBA=1;
UPDATE dbo.PAPELERA_REGISTRO SET ESTADO='ELIMINADO',NOMBRE=N'Registro eliminado',FECHA_RESOLUCION=SYSUTCDATETIME() WHERE ENTIDAD='ALUMNO' AND ID_REGISTRO='45999999' AND ESTADO='EN_PAPELERA';
INSERT dbo.AUDITORIA_SISTEMA(ENTIDAD,ID_REGISTRO,ACCION,ID_USUARIO_RESPONSABLE,NOMBRE_ACTOR,ROL_ACTOR,ES_PRUEBA,PROTEGIDO,MOTIVO)
 SELECT 'ALUMNO','45999999','LIMPIEZA_SQL',ID_USUARIO,NOMBRE_USUARIO,ID_ROL,1,1,'Limpieza explicita de fixture local SQL10' FROM dbo.USUARIO WHERE ID_USUARIO=@Administrador;
COMMIT; END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK; THROW; END CATCH;
